import{_ as t,o,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse(`{"title":"路由组件传参","description":"将 props 传递给路由组件 在你的组件中使用 $route 会与路由紧密耦合，这限制了组件的灵活性，因为它只能用于特定的 URL。虽然这不一定是件坏事，但我们可以通过 props 配置来解除这种行为： 我们可以将下面的代码 const User \\\\{ template: '\\\\。","frontmatter":{"title":"路由组件传参","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"将 props 传递给路由组件 在你的组件中使用 $route 会与路由紧密耦合，这限制了组件的灵活性，因为它只能用于特定的 URL。虽然这不一定是件坏事，但我们可以通过 props 配置来解除这种行为： 我们可以将下面的代码 const User \\\\{ template: '\\\\。","sidebarWeight":61,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/路由组件传参.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/路由组件传参.md","filePath":"posts/Vue系统教程/04-路由与状态管理/路由组件传参.md"}`),p={name:"posts/Vue系统教程/04-路由与状态管理/路由组件传参.md"};function a(n,e,u,c,d,i){return o(),r("div",null,[...e[0]||(e[0]=[s('<div><h1 id="路由组件传参" tabindex="-1">路由组件传参 <a class="header-anchor" href="#路由组件传参" aria-label="Permalink to &quot;路由组件传参&quot;">​</a></h1><blockquote><p>本节目标：理解“路由组件传参”的核心思路，并能把它用于实际开发或面试表达。 将 props 传递给路由组件</p></blockquote><p>在你的组件中使用 $route 会与路由紧密耦合，这限制了组件的灵活性，因为它只能用于特定的 URL。虽然这不一定是件坏事，但我们可以通过 props 配置来解除这种行为：</p><p>我们可以将下面的代码 const User = { template: &#39;&lt;div&gt;User {{ $route.params.id }}&lt;/div&gt;&#39; } const routes = [{ path: &#39;/user/:id&#39;, component: User }]</p><p>替换成 const User = { // 请确保添加一个与路由参数完全相同的 prop 名 props: [&#39;id&#39;], template: &#39;&lt;div&gt;User {{ id }}&lt;/div&gt;&#39; } const routes = [{ path: &#39;/user/:id&#39;, component: User, props: true }] 这允许你在任何地方使用该组件，使得该组件更容易重用和测试。</p><p><strong>布尔模式</strong> 当 props 设置为 true 时，route.params 将被设置为组件的 props。</p><p>命名视图 对于有命名视图的路由，你必须为每个命名视图定义 props 配置： const routes = [ { path: &#39;/user/:id&#39;, components: { default: User, sidebar: Sidebar }, props: { default: true, sidebar: false } } ]</p><p><strong>对象模式</strong> 当 props 是一个对象时，它将原样设置为组件 props。当 props 是静态的时候很有用。 const routes = [ { path: &#39;/promotion/from-newsletter&#39;, component: Promotion, props: { newsletterPopup: false } } ]</p><p><strong>函数模式</strong> 你可以创建一个返回 props 的函数。这允许你将参数转换为其他类型，将静态值与基于路由的值相结合等等。 const routes = [ { path: &#39;/search&#39;, component: SearchUser, props: route =&gt; ({ query: route.query.q }) } ] URL /search?q=vue 将传递 {query: &#39;vue&#39;} 作为 props 传给 SearchUser 组件。 请尽可能保持 props 函数为无状态的，因为它只会在路由发生变化时起作用。如果你需要状态来定义 props，请使用包装组件，这样 vue 才可以对状态变化做出反应。</p></div>',1)])])}const m=t(p,[["render",a]]);export{_ as __pageData,m as default};
